func reviewHeaderInventory(entries []os.DirEntry) [32]byte {
	h := sha256.New()
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
			fmt.Fprintf(h, "%s\x00%d\x00", entry.Name(), entry.Type())
		}
	}
	var result [32]byte
	copy(result[:], h.Sum(nil))
	return result
}

